  dsimp [StrictlyWeakerThan];
  constructor;
  . exact K4_weakerThan_GL;
  . apply System.not_weakerThan_iff.mpr;
    use (Axioms.L (atom 0));
    constructor;
    . exact axiomL!;
    . exact K4.unprovable_AxiomL;

